import type { FC, MouseEvent } from 'react';
import { useRef, useState } from 'react';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import portfolioData from '../data/portfolio.json';
import ProjectDialog from './ProjectDialog';

type Project = typeof portfolioData.projects[0];

interface ProjectCardProps {
  project: Project;
  index: number;
  onSelect: (project: Project) => void;
}

const ProjectCard: FC<ProjectCardProps> = ({ project, index, onSelect }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const pointerX = useMotionValue(0);
  const pointerY = useMotionValue(0);
  const springConfig = { stiffness: 220, damping: 20, mass: 0.6 };
  const rotateX = useSpring(useTransform(pointerY, [-0.5, 0.5], [10, -10]), springConfig);
  const rotateY = useSpring(useTransform(pointerX, [-0.5, 0.5], [-10, 10]), springConfig);
  const translateY = useSpring(useTransform(pointerY, [-0.5, 0.5], [6, -6]), springConfig);

  const handleMouseMove = (event: MouseEvent<HTMLDivElement>) => {
    const rect = cardRef.current?.getBoundingClientRect();
    if (!rect) return;
    pointerX.set((event.clientX - rect.left) / rect.width - 0.5);
    pointerY.set((event.clientY - rect.top) / rect.height - 0.5);
  };

  const handleMouseLeave = () => {
    pointerX.set(0);
    pointerY.set(0);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5, delay: 0.2 + (index * 0.1) }}
      style={{ perspective: 1000 }}
      className="h-full"
    >
      <motion.div
        ref={cardRef}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        onClick={() => onSelect(project)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') onSelect(project);
        }}
        role="button"
        tabIndex={0}
        aria-label={`View details for ${project.title}`}
        style={{ rotateX, rotateY, y: translateY, transformStyle: 'preserve-3d' }}
        whileHover={{ scale: 1.03 }}
        transition={{ type: 'spring', stiffness: 220, damping: 20 }}
        className="glass-panel group relative cursor-pointer hover:shadow-glow transition-shadow duration-300 h-full min-h-[180px]"
      >
        <div className="p-6 flex flex-col h-full">
          <h2 className="text-xl font-semibold mb-3 text-foreground group-hover:text-accent transition-colors tracking-tight">
            {project.title}
          </h2>
          <div className="flex flex-wrap gap-2">
            {project.technologies.slice(0, 5).map((tech) => (
              <span
                key={tech}
                className="px-2.5 py-1 text-sm rounded-full bg-background/50 text-accent border border-accent/30 font-medium"
              >
                {tech}
              </span>
            ))}
            {project.technologies.length > 5 && (
              <span className="px-2.5 py-1 text-sm rounded-full bg-background/50 text-accent border border-accent/30 font-medium">
                +{project.technologies.length - 5} more
              </span>
            )}
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

const ProjectGrid: FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  const handleProjectClick = (project: Project) => {
    setSelectedProject(project);
    setDialogOpen(true);
  };

  return (
    <section className="section-container pt-0 pb-12 md:py-1">
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className="text-center mb-8 md:mb-12"
      >
        <h1 className="text-2xl md:text-3xl font-display font-medium mb-6 text-accent">
          Featured Projects
        </h1>
        <p className="text-muted-foreground max-w-2xl mx-auto text-xl font-light leading-relaxed">
          projects that didn't break production
        </p>
      </motion.div>
      
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5 }}
        className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"
      >
        {portfolioData.projects.map((project, index) => (
          <ProjectCard
            key={project.title}
            project={project}
            index={index}
            onSelect={handleProjectClick}
          />
        ))}
      </motion.div>

      {dialogOpen && (
        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 bg-background/60 backdrop-blur-sm z-40"
        />
      )}

      <ProjectDialog 
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        project={selectedProject}
      />
    </section>
  );
};

export default ProjectGrid;
