import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import portfolioData from '../data/portfolio.json';

type Project = typeof portfolioData.projects[0];

interface ProjectDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  project: Project | null;
}

const ProjectDialog = ({ open, onOpenChange, project }: ProjectDialogProps) => {
  if (!project) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[95vw] sm:max-w-2xl lg:max-w-3xl max-h-[92vh] sm:max-h-[85vh] overflow-y-auto bg-card/95 backdrop-blur-md border border-border p-5 sm:p-8 rounded-xl">
        <DialogHeader className="space-y-4">
          <DialogTitle className="text-2xl sm:text-3xl font-bold text-accent">{project.title}</DialogTitle>
          <DialogDescription className="text-foreground/80 text-base sm:text-lg leading-relaxed">
            {project.description}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 mt-6">
          <div className="bg-background/30 border border-border p-4 rounded-lg">
            <h3 className="text-xl font-semibold mb-4 text-accent">Technologies Used</h3>
            <div className="flex flex-wrap gap-2">
              {project.technologies.map((tech) => (
                <span
                  key={tech}
                  className="px-3 py-1.5 rounded-full bg-background/50 text-accent border border-accent/30 text-sm font-medium"
                >
                  {tech}
                </span>
              ))}
            </div>
          </div>

          <div className="bg-background/30 border border-border p-4 rounded-lg">
            <h3 className="text-xl font-semibold mb-4 text-accent">Challenges</h3>
            <ul className="space-y-3 text-foreground/80">
              {project.challenges.map((challenge, index) => (
                <li key={index} className="flex items-start gap-2">
                  <span className="text-accent mt-1" aria-hidden="true">•</span>
                  <span className="leading-relaxed">{challenge}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="bg-background/30 border border-border p-4 rounded-lg">
            <h3 className="text-xl font-semibold mb-4 text-accent">Solutions</h3>
            <ul className="space-y-3 text-foreground/80">
              {project.solutions.map((solution, index) => (
                <li key={index} className="flex items-start gap-2">
                  <span className="text-accent mt-1" aria-hidden="true">•</span>
                  <span className="leading-relaxed">{solution}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="bg-background/30 border border-border p-4 rounded-lg">
            <h3 className="text-xl font-semibold mb-4 text-accent">Outcomes</h3>
            <ul className="space-y-3 text-foreground/80">
              {project.outcomes.map((outcome, index) => (
                <li key={index} className="flex items-start gap-2">
                  <span className="text-accent mt-1" aria-hidden="true">•</span>
                  <span className="leading-relaxed">{outcome}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default ProjectDialog;
